const TYPES = [{"type": "intro", "exemplars": [{"paper": "bertrand_schoar2003", "venue": "QJE", "head": "I. INTRODUCTION", "paragraphs": ["\"In the old days I would have said it was capital, history, the name of the bank. Garbage-it's about the guy at the top. I am very much a process person, a builder. Sandy [Weil] is an acquirer. Just totally different.\" -John Reed, CEO Citicorp How much do individual managers matter for firm behavior and economic performance? Research in finance and economics so far has given little consideration to this question. 1 Existing empirical studies typically rely on firm-, industry-, or market-level characteristics to explain corporate behavior and performance but largely ignore the possible role that individual managers may play in shaping these outcomes. Yet, a prevailing view in the business press and among managers themselves (as the quote by John Reed at the beginning of the paper suggests) is that CEOs and other top executives are key factors in the determination of corporate practices. Managers are often perceived as having their own \"styles\" when making investment, financing, and other strategic decisions, thereby imprinting their personal marks on the companies they manage. 2 The novel contribution of this paper is to explicitly introduce such a people, or manager, dimension in an empirical study of corporate practices. 3 The relevance of this approach is further underlined when we consider the large heterogeneity in corporate practices that is left unexplained by more standard models that rely only on firm-and industry-level factors. For example, research on the cross-sectional determinants of capital structure (e.g., Titman and Wessels [1988], Smith and Watts [1992], and Bradley, Jarrell, and Kim [1984]) shows that a large amount of variation remains unexplained after controlling for firm-level characteristics (such as market-to-book ratios, the type of assets a firm operates or 1. A few recent exceptions in the theory literature are papers by Rotemberg and Saloner [2000] and Van den Steen [2002]. These papers explicitly model the vision of the CEO as an important determinant of firm policy.", "2. To mention just one example, an article in a May 2001 issue of Business Week, titled \"The Koszlowski Method,\" discusses the aggressive acquisition style of Dennis Koszlowski, the CEO of Tyco.", "3. While the role of managers in shaping corporate practices has been virtually ignored in the economics and finance literature, there is a large body of work in the management science literature analyzing the determinants of decisionmaking among CEOs (see, for example, Hambrick and Mason [1984] or Waldman, Ramirez, House, and Puranam [2001]). Yet, both the specific focus of this literature and the methodological approach it follows differ substantially from the study we propose to undertake here. First, the outcome variables considered in the management literature are mostly process-related variables (e.g., communication process or charisma) rather than the actual economic outcomes we care about here. Second, most of the existing work in management science relies on case studies, laboratory experiments, or subjective survey responses, therefore lacking the level of generality of our approach. A paper that follows an empirical approach more closely related to ours is Lieberman, Lau, and Williams [1990], who find significant manager fixed effects in productivity in the U. S. and Japanese automobile industry. nondebt tax shields) or industry fixed effects. 4 In a similar vein, the ongoing debate about differences in investment to cash flow and investment to Q sensitivities [Fazzari, Hubbard, and Petersen 1988; Kaplan and Zingales 1997] highlights the considerable disagreement as to the roots of the wide variation in investment behavior across firms. One primary objective of this paper is to ask whether managers' personalities, as opposed to firm, industry, or market factors, can in part account for these unexplained differences.", "Intuitively, we want to quantify how much of the observed variation in firm policies can be attributed to manager fixed effects. Since manager effects might be correlated with other firm-specific characteristics, we estimate the role of managers in a framework where we can control for observable and unobservable differences across firms. For this purpose, we construct a manager-firm matched panel data set, where we track individual top managers across different firms over time. This allows us to estimate how much of the unexplained variation in firm practices can be attributed to manager fixed effects, after controlling for firm fixed effects and time-varying firm characteristics. 5 The specific corporate variables we study relate to investment policy (capital expenditures, investment to Q sensitivity, investment to cash flow sensitivity, and acquisition policy), financial policy (financial leverage, interest coverage, cash holdings, and dividend payouts), organizational strategy (R&D expenditures, advertising expenditures, diversification policy, and costcutting policy), and performance. 6 Our results show that manager fixed effects are empirically important determinants of a wide range of corporate variables. On average, adding the fixed effects to models of corporate practices that already account for observable and unobservable firm characteristics results in increases in adjusted R 2 's of more than four percentage points. More interestingly, we find that manager 4. For a recent study of intraindustry variation in leverage, see MacKay and Phillips [2002].", "5. A few recent papers relate managerial characteristics to firm performance and investment. See, for example, Malmendier and Tate [2002] and Wasserman, Nohria, and Anand [2002]. However, these papers do not control for firm fixed effects and therefore cannot separate manager effects from firm effects. In a more recent paper Malmendier and Tate [2003] use a methodology more similar to ours. They track switchers across firms to study the effect of managerial overconfidence on acquisition behavior.", "6. The fixed effects approach used in this analysis intends to measure whether there is persistence of managerial style over time and across different jobs. This is the very definition of \"style\" used in this paper. But we do not want to rule out that managers may learn or develop their style over time.", "effects matter much more for some decisions than others. Manager fixed effects appear to be especially important in acquisition or diversification decisions, dividend policy, interest coverage, and cost-cutting policy.", "By correlating these estimated manager fixed effects across different corporate variables, we are also able to identify some overarching patterns in managerial decision-making. Among other things, we find that managers seem to differ in their approach toward company growth and in their financial aggressiveness. Managers who engage in more external acquisitions and diversification also display lower levels of capital expenditures and R&D. We also find that managers who have high investment to Q fixed effects rank lower in their investment to cash flow sensitivity (and vice versa), suggesting that managers may differ, all else equal, in the benchmark that they use when making investment decisions.", "These results provide evidence that top executives vary considerably in their management \"styles\" and thereby suggest a rather novel approach for corporate finance research. Yet, they also raise questions as to why managers may behave so differently in apparently similar economic environments. Do these findings reflect differences in preferences, absolute or relative skills, or opinions? More importantly, what are the efficiency implications of these findings? While these questions outline clear directions for future work, we provide some preliminary evidence on some of these issues. First, we show that the differences in managerial practices documented above are systematically related to differences in performance. More precisely, we show that there are significant managerial fixed effects in performance and these effects are statistically related to some of the fixed effects in corporate practices. For example, managers who are more investment-Q sensitive, and have higher administrative expenses, and are less active in the acquisition and diversification markets also have lower performance fixed effects. In addition, we show that managers with higher performance fixed effects also receive higher salary and total compensation and that these managers are more likely to be found in better governed firms. These results are suggestive of possibly important efficiency implications of our findings.", "In a final step, we tie back differences in style to observable managerial characteristics. The two characteristics we consider are birth cohort and MBA graduation. We analyze the extent to which corporate decisions are affected by these two characteristics, after controlling for any fixed differences across firms and other time-varying firm factors. We find that older generations of CEOs appear overall more conservative in their decision-making. On the other hand, managers who hold an MBA degree appear overall to follow more aggressive strategies.", "The rest of this paper is organized as follows. Section II provides a brief discussion of alternative hypotheses as to why individual managers may matter for corporate decisions. Section III presents the different data sources, describes the construction of the data set, and defines the main variables of interest. Section IV quantifies the importance of manager fixed effects for various corporate practices, and Section V discusses possible efficiency implications of these findings. Section VI studies birth cohort and MBA graduation as two specific determinants of managerial style. Section VII summarizes and offers some concluding remarks."]}, {"paper": "bushee2018", "venue": "JAR", "head": "Introduction", "paragraphs": ["An extensive prior literature examines the relation between the linguistic complexity of corporate disclosures and various firm outcomes. This literature generally interprets the use of complex language as an intentional choice by managers to obfuscate in order to increase information processing costs and delay the market reaction to news (e.g., Li [2008]). An alternative view is that complex language could be necessary to convey information about the firm's business transactions and operating strategy (e.g., Bloomfield [2008]). In reviewing the literature on linguistic complexity, Loughran and McDonald [2016] conclude, \"researchers face the problem of separating the business and the document. These issues are intertwined because the document attempts to describe the economic reality of the business\" (p. 1198).", "In this paper, we show that linguistic complexity commingles two latent components that have opposite relations to information asymmetry: an \"information\" component and an \"obfuscation\" component. The information component represents linguistic complexity attributable to informative technical disclosure about the business. The obfuscation component represents linguistic complexity intended to reduce the informativeness of the disclosure. As a result of this commingling, the relation between overall linguistic complexity and information asymmetry is theoretically ambiguous. In contrast, we show that the relations between the two latent components of linguistic complexity and information asymmetry are theoretically unambiguous; that is, the information (obfuscation) component is negatively (positively) associated with information asymmetry.", "We develop an empirical approach to estimate the latent components of linguistic complexity within the context of quarterly earnings conference calls. The key to our approach is to identify the portion of the linguistic complexity that represents managers' appropriate disclosure response to business complexity in the absence of obfuscation. We exploit the fact that conference calls allow us to observe the linguistic complexity of an outside party-security analysts-in the same setting as the manager's linguistic complexity. Prior research finds that analysts have incentives to acquire and convey value-relevant information (Mayew [2008], Twedt and Rees [2012]), suggesting that they are unlikely to have obfuscation incentives during the call. As such, we use analysts' linguistic complexity as a benchmark for estimating the two latent components. We then validate our approach by examining the relation between our estimates of the two latent components and information asymmetry.", "We first follow prior work and examine the association between overall managerial linguistic complexity and information asymmetry. Following an extensive prior literature, we measure linguistic complexity using the Gunning [1952] Fog index and information asymmetry using the Amihud [2002] measure of illiquidity. As conference calls include both scripted presentations and more spontaneous responses to questions, we separately examine the presentation and the response portions of the call. Consistent with prior work that suggests that the linguistic complexity of 10-Ks reflects obfuscation, we find a positive relation between managerial Fog in the presentation and information asymmetry. However, we find a negative relation between managerial Fog in the response and information asymmetry. While these results suggest that the informativeness of linguistic complexity differs between scripted and spontaneous language, our analysis of the latent components suggests a more nuanced conclusion.", "Specifically, when we decompose linguistic complexity into its two latent components, we find a negative (positive) relation between the estimated information (obfuscation) component and information asymmetry. These findings are similar for both the presentation and response. These results illustrate that the relation between overall linguistic complexity and information asymmetry is ambiguous because complex language is driven by two components that have opposite relations to information asymmetry. In contrast, our decomposition shows that the relation between the components themselves and information asymmetry is unambiguous.", "Finding that the two latent components have opposite relations with information asymmetry should mitigate concerns that our estimates are biased in any one direction. For example, if our estimate of the information component contains some obfuscation, it would bias the negative (positive) coefficient on the information (obfuscation) component upward (downward) and hence bias against finding opposite directional effects. While any empirical estimate of an unobserved latent variable will have some amount of noise and bias, our findings suggest that the noise and bias is sufficiently mild that our estimates are empirical descriptive of the underlying theoretical constructs.", "Our results are robust to a variety of sensitivity tests. First, the results hold (and in some cases become stronger) when we control for other language attributes, such as number of words, industry jargon, forward-looking statements, and tone. Second, the results are robust to controls for precall information asymmetry and to estimating a within-industry, within-firm, and within-manager analysis, suggesting that time-series variation in these components explains time-series variation in information asymmetry. Third, the results hold under three Monte Carlo placebo tests that use randomly selected nonevent days, alternative conference call days, and language from another firm's conference call. Fourth, we further validate our measures by showing that the information (obfuscation) component is positively (negatively) associated with the likelihood that managers provide quantitative earnings guidance on the call, as would be expected if managers act consistently in their qualitative and quantitative voluntary disclosure decisions.", "Finally, we examine our decomposition for loss firms. Prior work finds that loss firms exhibit greater linguistic complexity in their 10-Ks and attributes this finding to managerial obfuscation of poor performance (Li [2008]). An alternative interpretation is that managers of loss firms provide more information to explain poor performance (Bloomfield [2008]). While it might be more satisfying to attribute the higher Fog of loss firms to either greater obfuscation or greater information, our results suggest both forces are present. We find that loss firms have significantly greater values of both information and obfuscation components during calls. Thus, controlling for obfuscation, managers of loss firms provide more information. However, managers of loss firms also obfuscate to a greater extent. Collectively, we find that identifying the latent obfuscation and information components of linguistic complexity provides more powerful tests of the relation between linguistic complexity and capital market outcomes.", "Our paper contributes to the large stream of literature that examines the linguistic complexity of corporate disclosures. Following Li [2008], most of the prior literature focuses on linguistic complexity in 10-K filings and interprets complex language as obfuscation (see Loughran and McDonald [2016] for a review). Recent papers by Guay, Samuels, and Taylor [2016] and Dyer, Lang, and Stice-Lawrence [2017] suggest that the linguistic complexity of 10-Ks could also be the result of accounting standards (e.g., FAS 133 and 157) and assume that regulatory-induced complexity results in less informative disclosures. By decomposing linguistic complexity into its latent information and obfuscation components, we show that complex language can result in more informative disclosure. This finding provides an important contrast to prior literature that assumes that complex language necessarily renders disclosures less informative. Moreover, our finding that the latent components have countervailing effects on information asymmetry potentially explains the mixed empirical results that relate measures of overall linguistic complexity to measures of information content (e.g., Loughran and McDonald [2014]) and to fraudulent behavior (e.g., Hoberg and Lewis [2015]).", "We also provide a new empirical approach that future researchers can use to improve construct validity for other linguistic measures. Our conference call setting provides us with several advantages in this regard. First, the language on conference calls is less driven by regulation and accounting standards than that in mandatory SEC filings, which reflects considerable boilerplate language that usually does not vary from period to period. Thus, the language on conference calls is more likely to reflect an intentional disclosure choice by managers. This notion is in the spirit of the reporting incentives literature, which finds that managers use discretion both to inform and to obfuscate (e.g., Leuz and Wysocki [2016]). Second, conference calls allow us to observe the linguistic complexity of security analysts, who are outside of the firm's financial reporting system and have little or no incentive to obfuscate in their language. Thus, analysts provide a benchmark level of linguistic complexity that is unique for a specific conference call. This approach is in contrast to prior work, which predominantly uses industry-level benchmarks to estimate firm-level discretionary reporting decisions (e.g., discretionary accruals) and suffers from an inability to cleanly separate reporting decisions from the firm's economic activity (e.g., Leuz and Wysocki [2016], Loughran and McDonald [2016]). While our approach is also susceptible to the difficulty of separating economics and reporting decisions, finding opposite relations between the latent components and information asymmetry suggests that our estimates of these components are empirically descriptive.", "The remainder of the paper proceeds as follows. Section 2 reviews the relevant prior literature. Section 3 describes our research design. Section 4 presents the sample and descriptive statistics. Section 5 presents our findings, and section 6 concludes."]}, {"paper": "dwz", "venue": "working(FWP)", "head": "Introduction", "paragraphs": ["In this day and age of big data, market participants have an astonishing array of company information available at the click of a mouse. Yet direct, personal interactions with management remain among the most coveted ways to learn about company prospects. Conference calls are a standard accompaniment to the release of quarterly earnings reports, and one that is almost always attended by top executives (Lev, 2012). In addition, a growing body of evidence points to the importance of investor meetings (So, Wang, and Zhang, 2021).", "It is an open question why market participants would show such an interest in personal interactions with managers. The seemingly obvious reason would be to obtain private information. However, given the proliferation of data as well as rules mandating equal access to information, such as Regulation Fair Disclosure (Reg FD), it is increasingly hard to argue for this explanation. Alternatively, the object of interest are the managers themselves -do they have a good grip of the business and a clear vision of its future? Or do they appear confused and fuzzy? Under this alternative explanation, how managers communicate becomes equally important as what they actually say. Investors and the analysts, who serve them, expect managers to paint a clear picture of the company that will help them in determining its value. 1 In this paper, we propose a method for evaluating CEO clarity and test its implications for companies' stock price and long-term value.", "Although the word \"clarity\" is simple enough, a precise definition is elusive. (Some dictionaries somewhat unhelpfully define clarity as the state of being clear.) The philosopher Ren\u00e9 Descartes defines a clear thought, or perception, through the following analogy to the physical world: \"I call a perception 'clear' when it is present and accessible to the attentive mind -just as we say that we see something clearly when it is present to the eye's gaze and stimulates it with a sufficient degree of strength and accessibility\" (Descartes, 1985, p. 207). Thus, something that cannot be seen at all also cannot be seen clearly. Moreover, the definition suggests that clarity is a spectrum, increasing with the strength of the stimuli.", "To arrive at an empirically useful measure of CEO clarity, we make two design choices, one regarding what exactly to measure and the other where to measure it.", "As for the what, we focus on the CEOs' use of words such as \"approximately\", \"probably\", and \"maybe\", as compiled in the Loughran and McDonald (2011) \"uncertainty\" wordlist.", "These are cautious words that qualify any message conveyed. 2 Frequent use of such words indicates lack of \"sufficient degree of strength,\" or clarity in CEO communication. However, this lack of clarity could also reflect persistent characteristics related to the firms' communication culture or business model. It could also reflect current conditions at the firm. In times of economy-wide, industry-wide, or firm-specific crisis, we would expect managers to use uncertainty words more frequently; definite statements seem less likely when the world is, in fact, complex and confusing. In light of these considerations, we operationalize CEOs' clarity as the stable \"style\" component in the use of uncertainty words -the component that is not motivated by business uncertainty. 3 Teasing apart CEO clarity (\"style\") from the other components just mentioned is challenging. This challenge motivates to choose quarterly earnings conference calls as the setting where we assess CEO communication. In every quarter, managers conduct such calls to discuss recent financial results and the outlook for their companies. The calls begin with a prepared presentation, followed by a Q&A session with participating security analysts. 4 Importantly, the conference call setting allows ready comparison of a fully scripted presentation (prepared remarks) and a necessarily more improvised set of answers (the Q&A session) delivered by the same person about the same firm and on the same date, hence under identical business conditions. Comparing the two parts of the call, we can filter out the effects of time-varying uncertainty, which affects both parts. It also allows us to separate CEO style, which we expect to show mostly in the Q&A, from the firm's culture, which we expect to dominate in the presentation part.", "We analyze a sample of conference calls held by public U.S. companies from 2003 through 2015. We begin by regressing CEOs' frequency of uncertainty words in answers on (1) the CEO's fixed effect, (2) the CEO's own frequency of uncertainty words during the presentation (to control for unobservable firm-level factors that influence clarity at the time of the call), and (3) other time-varying controls. Those controls include other features of the CEO's speech, the analysts' questions, and the firm's recent performance. Prior research, discussed below, has also exploited the differences between presentations and answers. Our analysis is novel in that it focuses on the fixed effect extracted from this decomposition and defines CEO clarity as inversely proportional to this fixed effect.", "We find that CEOs differ substantially in clarity. This variability cannot be explained by firm-level uncertainty; neither does it differ systematically across industries, firm size, or manager age. Clarity also correlates only very weakly with firm-level uncertainty, as indicated by dispersion in analyst forecasts and stock price volatility. Firms for which intangibles form an important part of their assets actually tend to be led by clear CEOs.", "These results confirm that the clarity of CEOs' communication is a personal characteristic, and is distinct from the types of firms they run.", "Next, we show that CEO clarity matters for the market -investors and analysts respond more strongly to information conveyed by clear CEOs. This is consistent with the view that market participants interpret the current earnings report in the context of a broad understanding of a company and its management. That understanding requires repeated interactions. Hence, persistent features of communication, such as CEOs' clarity, matter most. By contrast, residual use of uncertainty words -that is, the component of the overall frequency of uncertainty words in CEO's answers during each call that is not explained by items (1) to ( 3) above -explains little of the market reaction. The results persist when we control for other important determinants of stock price reactions to conference calls, including a range of variables that proxy for uncertainty and the fraction of intangibles.", "These results also hold in the sample of firms that experienced CEO turnover. In the turnover sample, we are able to control for firm-fixed effects. That is, unobserved firm characteristics that correlate with earnings responses would have to change systematically with a switch in CEOs to otherwise explain our results. 5 The effects are sizable. The two-day absolute stock price response to a conference call is 9 basis points higher than average when the CEO has clarity one standard deviation above the mean. That quantity is roughly 1/5 of the effect of a one-decile move in the absolute earnings surprise. CEO clarity has similar powerful effects on abnormal trading volume and the revision of analysts' earnings forecasts.", "What explains these effects? Seeking an answer, we interact clarity with the earnings surprise and with unexpected linguistic negativity of the call. We find that high clarity (a) intensifies responses to fundamental information, and (b) this intensification is particularly strong with respect to the price impact of soft information.", "Clear CEOs, these results suggest, simply convey more information. If so, the stronger initial response should be permanent, and subsequent returns should be similar for all firms.", "A plausible alternative explanation is that fuzzy communication simply takes longer to process. In this case, firms with fuzzy CEOs would experience a stronger return drift after conference calls. A second alternative explanation is that CEOs are generally overconfident and that investors overreact to their words. If so, stock returns would revert after the initial stronger reaction to clear CEOs' earnings surprises. In fact, we find that clear-and fuzzy-talking CEOs experience equivalent post-call drift, which refutes both alternative explanations. The market finds clear CEOs to be more informative.", "Moreover, when a clear-talking CEO is appointed in a turnover, firm value on average increases. The economic magnitude is substantial; an increase in clarity by one standard deviation is associated with an increase of Tobin's Q by 0.081 units (averaged over the tenures of the two CEOs), which for the median firm translates to around $77 million in added market value.", "That increase in value comes although clear CEOs do not appear to be better managers in general -they perform on par with their fuzzy counterparts on standard metrics of operating performance. Nevertheless, analyst recommendations become more favorable when clear CEOs are appointed, which suggests such managers are better perceived externally. We find no evidence that firms tend to hire clear CEOs depending on recent valuations or operating performance. That negative finding diminishes concerns of assortative matching on CEO clarity. Moreover, clear CEOs do not reap the value their style creates; they get paid no more than their fuzzier peers. Taken together, these results suggest that clear talk is a significant source of firm value, though one that is insufficiently recognized by the firms themselves.", "Our study makes three contributions. It introduces a simple measure of CEO clarity, a novel dimension of oral communication whose implications have not been documented in the literature. 6 An important consideration when examining oral communication by 6 The vast majority of existing papers in the conference call literature focus on the linguistic tone of the language used by managers and analysts on these calls (see Henry and Leone (2016) and Loughran and McDonald (2016) for surveys). The use of uncertainty words in written communication was studied by Loughran and McDonald (2013), who show that a high fraction of uncertain words (as well as negative words and weak modal words) in IPO prospectuses produce higher first-day IPO returns and greater volatility, and Ertugrul, Lei, Qiu, and Wan (2017), who show that firms with larger 10-K file sizes and a higher proportion of uncertain and weak modal words in their 10-Ks accept stricter loan contract terms and suffer a greater future risk of a stock price crash. Demers and Yu (2014) show that linguistic certainty in managerial announcements reinforces the precision of the contemporaneously provided numerical forecast. In their analysis of managerial tone Druz, Petzev, Wagner, and Zeckhauser (2020) control for the frequency of uncertain words, but they do not explore the potential of uncertainty talk to impede the incorporation of news in prices. Moreover, they control for firm/CEO fixed effects and thus focus on the time-varying components of speech variables, rather than on the stable communication style of managers. Most closely related to our work, Demers and Vega (2011) find that greater linguistic certainty in written earnings announcements leads to a stronger immediate response to earnings news and less drift. We discuss the literature on managerial strategies in conference calls in Section 2.", "individual managers (as opposed to written company documents) is the extent to which any linguistic features and their associated economic effects reflect time-varying, potentially strategic behavior as opposed to being a persistent personal characteristic -a form of \"style.\" Davis, Ge, Matsumoto, and Zhang (2015) show that CEOs exhibit distinctive styles in the tone of conference calls (some are more optimistic than others), but they do not examine its impact on market reactions. Other papers, including those that focus on how information is conveyed, such as Lee (2016), sidestep this issue by including manager fixed effects in their outcome regressions. Our analysis is the first to explicitly decompose an important feature of CEO communication into two components: personal style and the potentially strategic component (the residual), and then to separately examine their impacts.", "Methodologically, our analysis advances the style literature in two ways. First, it demonstrates how the special setting of conference calls permits style to be isolated, without having to focus on manager transitions (Bertrand and Schoar, 2003). This significantly expands the sample size and avoids the critique of Fee, Hadlock, and Pierce (2013), who argue that the special nature of manager transitions obscures the effects of style. Second, it quantifies CEO clarity (our style variable) and examines its economic consequences. In other words, it tests for directional effects, rather than the mere existence, of style with respect to various firm-level variables. Adams, Keloharju, and Kn\u00fcpfer (2018) also extract CEO fixed effects, though they still rely on manager transitions. Our method can be employed to study the existence and relevance of style in other speech characteristics and for a broader sample of CEOs.", "Finally, we discover several novel empirical findings. They establish CEO clarity as a significant aspect of corporate communication, and, importantly, one that is relevant for how investors value companies. This adds to evidence from studies such as Engelberg (2008) and Loughran and McDonald (2011), which highlight the importance of \"soft\" information contained in textual disclosures. In particular, Loughran and McDonald (2014) and Hwang and Kim (2017) show that how information is presented in written communication matters for investor decisions and financial outcomes. We show that this holds for spoken communication as well. Top managers, above all CEOs, verbally communicate fundamental information, on earnings conference calls. How they talk affects how information is processed by the markets.", "The paper proceeds as follows. Section 2 uses the extant literature to develop three hypotheses. Section 3 discusses the conference call data. Section 4 shows how to parse the roles of firm characteristics and CEO style in explaining word choice in the presentation and Q&A parts of the call as well as introduces our measure of clarity. Section 5 presents evidence on the economic importance of CEO clarity for analyst and investor responses.", "Section 6 explores the relationship of CEO clarity to firm value. Section 7 concludes."]}, {"paper": "harford1999", "venue": "JF", "head": "", "paragraphs": ["DESPITE THE IMPORTANCE OF CASH RESERVES to theories in corporate finance, corporate holdings of cash have received relatively little direct attention in the academic literature. Much of the literature on cash reserves is older and either descriptive or concerned with corporate transaction demand for cash. 1 However, the role of cash in the corporation is much broader. In the presence of capital market imperfections deriving from asymmetric information between managers and capital providers, liquidity can take on a strategic role. Managers can increase firm value by managing their cash balances as buffer stocks. These buffer stocks allow the firm to maintain the ability to finance investments even when current cash f lows are insufficient to meet the firm's investment demands.", "Thus, cash reserves provide benefits to equity holders by reducing the underinvestment problem. Managers wishing to avoid the costs associated with external financing in an imperfect information environment find it optimal to maintain sufficient internal financial f lexibility to allow them to reduce the underinvestment problem. Further, since the equity holders suffer the loss from underinvestment, they find it value increasing for managers to maintain the buffer stock of cash.", "However, cash reserves have large potential costs in addition to their benefits. The same freedom from external financing that makes cash reserves valuable to equity holders can be abused by managers. Easterbrook ~1984! posits that frequent trips to the capital markets help control the agency conf lict between shareholders and managers. Plentiful internal financing reduces the effectiveness of this control mechanism. Jensen and Meckling ~1976! and Jensen ~1986! have emphasized the agency conf lict that exists between owners and managers. Jensen ~1986! argues that this conf lict is most severe in the presence of large free cash f lows, or cash f lows above what is needed to meet payments to stakeholders and fund positive net present value ~NPV! projects. Equity holders would prefer that cash above the optimal buffer level of reserves be paid out. However, managers may value the freedom from monitoring by external capital providers that this capital provides them. Jensen ~1986! notes that acquisitions are a primary method by which managers can spend cash instead of paying it out to their shareholders. Managers' desire to reduce their personal undiversified risk or increase the scope of their authority may lead them to make investments that are not value increasing for the shareholders. Since excessive cash reserves are essentially stockpiled free cash f low, this agency cost of free cash f low should be severe in cash-rich firms. The main objective of this study is to determine whether the presence of excess cash leads managers with discretion to make value-decreasing investment decisions. I focus on acquisitions, which are large and observable outcomes of the investment decision process.", "I begin with a brief discussion and examination of how corporations use cash. Drawing on inventory management and buffer-stock theories of cash management, a baseline model of normal cash reserves is developed. A reduced form of the model is estimated using data from U.S. corporations for the period 1950 to 1994. I use the model to identify cash-rich firms-firms that have accumulated cash reserves above the predictions of the model.", "Since these cash-rich firms can shed light on the agency conf lict over firm resources, the rest of the paper examines managers' behavior with respect to determining whether their cash positions and acquisition decisions can be explained by the free cash f low hypothesis. The underlying alternative hypothesis is that capital market imperfections are costly enough that firms find it optimal to save to fund large expenditures, such as a planned acquisition.", "I find that the behavior of cash-rich firms is consistent with the predictions of the free cash f low hypothesis. This conclusion is based on several pieces of evidence. Cash-richness predicts that a firm will become a bidder, even controlling for stock price performance and sales growth. Further, the abnormal stock price reaction to acquisition bid announcements by cash-rich bidders is negative and decreasing in the amount of excess cash held by the bidder. I examine the characteristics of cash-rich bids to explain this result, and find that the proportion of cash-rich firms undertaking diversifying acquisitions is significantly higher than the proportion of cash-poor firms doing so. The targets of cash-rich firms are also significantly less likely to attract other bidders. Consistent with this, the operating performance of the bidder0target combination in successful cash-rich bids declines significantly following the bid-consistent with the negative market reaction at the announcement. I conclude that cashrich firms engage in value-decreasing behavior. Furthermore, the stock market appears to partially anticipate this behavior, as evidenced by the negative stock market reaction to cash stockpiling.", "In the next section, I provide an overview of the testable hypotheses regarding cash reserves, develop a model of normal cash, and present descriptive statistics on industry cash holdings and cash-rich firms. In Section II, I empirically test the predictions of the free cash f low hypothesis. Section III presents some further tests of the implications of the results of Section II, and Section IV concludes."]}, {"paper": "hollander2010", "venue": "JAR", "head": "Introduction", "paragraphs": ["In accounting research, the issue of incomplete disclosure is a sensitive one. Early disclosure theories propound that complete (i.e., full) disclosure is optimal. The adverse-selection problem inherent in the buying and selling of company shares is said to compel the seller to fully disclose to the buyer (see Grossman and Hart [1980], Grossman [1981], Milgrom [1981]). These models argue that full disclosure occurs through a process known as unraveling. This notion that the behavior of rational buyers can unravel withheld information is a \"seminal result that forms the basis for nearly all of the subsequent research\" (Verrecchia [2001, p. 141]). Drawing on empirical observations of incomplete disclosure, subsequent research posits several theories for why it occurs. For instance, if disclosure comes at a cost (e.g., fixed disclosure cost in Verrecchia [1983], or variable proprietary cost in Wagenhofer [1990]), then incomplete disclosure can occur in equilibrium. Nonetheless, while incomplete-disclosure equilibria can occur when firms face proprietary costs, Wagenhofer [1990] shows that such equilibria arise only sporadically. 1Nevertheless, the empirical literature on incomplete disclosure is scant (Kothari, Shu, and Wysocki [2009]). The difficulty of measuring incomplete disclosure may, in part, account for this. Prior studies use selfconstructed measures like analyst ratings of firms' disclosures (i.e., Association for Investment Management and Research (AIMR) scores), the frequency of management earnings forecasts (e.g., Nagar, Nanda, and Wysocki [2003]), segment reporting choices (e.g., Harris [1998]), and the magnitude of stock-price responses (Kothari, Shu, and Wysocki [2009]). Such measures, however, are problematic for two reasons. First, they are somewhat indirect. Leuz and Verrecchia [2000], for example, highlight the difficulty of basing inferences on analyst ratings analysis given that AIMR scores only measure an analyst's perception of the quality of the firm's disclosure. In the case of management earnings forecasts, a low frequency of such disclosures can be due to lack of demand. More importantly, this measure cannot be used to challenge the alternative explanation that, in fact, no news gives rise to lower frequencies of earnings guidance. Second, some of these measures make it difficult to isolate the impact of incomplete disclosure because they presume that investors expect such disclosures to occur at a particular time (and that investors would therefore react negatively when these disclosures do not occur). In their review paper, Healy and Palepu [2001] conclude that problems such as endogeneity and measurement error in these studies make it \"difficult to interpret their findings\" (p. 407).", "Given the above, our study exploits the open nature of conference calls to explore whether managers suppress information that is in demand. 2 Managers' reluctance to spoon-feed information to participants on the conference call in public avoids some of the aforementioned problems because incomplete disclosure in this context is a well-defined event and call participants' demand for information is readily discernible. We therefore address the following three questions: Do managers withhold information from conference call participants? If so, under what conditions do managers withhold information? And, finally, do investors interpret this incomplete disclosure negatively?", "A survey by the Association for Investment Management and Research (AIMR [2000]) indicates that, when analyzing a company, investment professionals consider corporate executives to be important sources of information. Oral communications with management, in particular, are deemed essential. To facilitate such meetings, firms conduct conference calls using company Web sites and/or Webcasts over the Internet. It is widely held that companies use these live meetings to bridge the information gap between managers and outside investors (e.g., Tasker [1998a]). While this may be true, in practice managers regularly leave call participants in the dark about important issues. 3 To illustrate, consider the recent case of Apple Inc. On the Q3-2008 conference call, Apple executives refused to answer an analyst's question about CEO Steve Jobs's health, replying, \"Steve's health is a private matter.\" Many Wall Street analysts and investors, however, were 2 We use the terms manager and firm interchangeably in the study. All things considered, it is the manager who acts on behalf of the firm. We do, however, recognize that the preferences of a manager and those of a firm are not necessarily congruent. Therefore, we also examine the relation between managers' disclosure activities and their stock price-based incentives.", "3 A Boston-based company called Business Intelligence Advisors (BIA) employs a number of former CIA and other national-security operatives to perform behavior analyses of corporate executives to detect when managers are being less than open or outright lying in their communications with shareholders. Its specialists try to gauge whether, during interviews, earnings conference calls, press releases or management discussions in 10-Ks, managers definitively and directly answer questions and forthrightly address issues or tap dance around subjects. Hedge funds constitute BIA's primary customers. Laing [2006] discusses several examples of assessments conducted by BIA analysts. For instance, \"JPMorgan Chase CEO Jamie Dimon scores fairly well on the candor front in a recent earnings conference call by forthrightly dealing with his concerns over the bank's credit-card growth and the likely rise in nonperforming commercial loans.\" Kodak executives, on the other hand, \"in their latest earnings conference call, were less than open about the company's back-to-school sales prospects, in-store kiosk results and campaign to boost operating margins.\" And, as if General Motors didn't have enough problems, \"the analysts give its management low marks for openness and credibility.\" crying foul, saying that \"Apple is Steve Jobs and Steve Jobs is Apple.\" Moreover, the incident was widely covered in the press (e.g., \"Talk of Chief's Health Weighs on Apple's Share Price,\" The New York Times, July 23, 2008; \"Apple's Culture of Secrecy,\" The New York Times, July 26, 2008). Although analysts disagree about the role played by the communication concerning Mr. Jobs's health, Apple's shares dropped by 2.6% that day despite an alltime high in earnings for Q3-2008. This example demonstrates that being less than candid in one's communication with the investing public can have serious economic consequences.", "Practitioners and regulators agree that managers tend to withhold private information from the market, even in renowned disclosure environments like the United States. A panelist at the 2001 Stern Stewart Executive Roundtable pronounced, \"all things equal, the managers of most companies would rather not disclose things if they don't have to . . . obfuscation serves their interests; it gives them another degree of freedom in producing results that are acceptable to stockholders\" (Stewart [2001, p. 37]). In Special Study: Regulation Fair Disclosure Revisited, SEC Commissioner Laura S. Unger states that \"[t]o explain why less information may be publicly available, many issuers noted that, post-Reg FD [Regulation Fair Disclosure], companies have shifted disclosure oversight from the investor relations department to the legal department. Generally, the legal department adopts the conservative stance of wanting to say nothing for fear of running afoul of Reg FD\" (Unger [2001]).", "We manually reviewed call transcripts for a large sample of randomly selected earnings-related calls held by publicly listed U.S. firms between January 1 and December 31, 2004 to uncover whether managers withhold requested information. More specifically, we determine whether or not each request for information made during the call is granted. If at least one request is not granted, we mark this call as containing incomplete disclosure. We find that managers withhold information from the public in approximately 6 out of 10 calls, with an average of two unanswered queries per call, a frequency greater than is often assumed. The replies vary from a direct \"No, we do not want to provide that information\" to more subtle responses that nevertheless indicate that the demand for information will not be met. Moreover, most unanswered questions concern the given company's financials (especially sales and margins), which comports with sellside financial analysts' primary task of producing earnings forecasts for the stocks they follow as part of their investment recommendations (Schipper [1991]).", "Next, to shed light on managerial intent, we explore under what conditions managers of firms in the Standard & Poor's (S&P) 1500 index (i.e., S&P 500, S&P 400 MidCap, and S&P 600 SmallCap) withhold information. We focus our analysis on S&P 1500 firms because Merton's [1987] awareness model holds that for disclosures to be effective a firm must command some degree of visibility. Given that firms in the S&P 1500 index have a large shareholder base (i.e., a large number of investors are aware of the firm's existence), investors are expected to trade in real-time on information released (or withheld) during a call (Peng [2005]). As a consequence, the managers of these firms are strongly incentivized to align themselves with investors' disclosure preferences.", "Based on prior studies on ex ante disclosure, we hypothesize that when disclosure costs are high, companies avoid publicly disclosing their private information. Measures of disclosure costs net of benefits that have explanatory power include (among others) company size, firm performance, and litigation risk. In support of the claim that analysts play an important role in uncovering (vs. simply repackaging) information about the firm, we find that when analysts are actively involved during a call (i.e., by asking an unusually large number of questions) managers are more likely to not answer these questions. We also study how stock price-based compensation might operate as an incentive mechanism for eliciting disclosure. Given that, in light of the current contingencies, stock prices impound the relevant information in managerial disclosures, Nagar, Nanda, and Wysocki [2003] predict that incentives based on stock price will encourage managers to disclose both good and bad news. We support this prediction by documenting a positive association between a corporate executive's stock price-based incentives (as measured by both a CEO's stock-based compensation and share ownership) and how forthcoming firms are when it comes to disclosing information.", "Assuming that analysts participate in calls to hunt for information that is relevant not only to them but likewise to the market, we dedicate the final section of the study to investigating how incomplete disclosure impacts investor trading during the time frame of the call. Several theories link incomplete disclosure with a firm's market valuation (e.g., Verrecchia [2001]). One economic consequence commonly associated with a firm's disclosure choice is how severe the adverse selection problem, which is inherent in the buying and selling of firm shares, becomes. Less disclosure should exacerbate adverse selection, thereby increasing how much parties to a transaction involved in the buying or selling of firm shares need to price-protect themselves (Dye [1985], Diamond and Verrecchia [1991]). This principle, known as unraveling , assumes that investors interpret withheld information as unfavorable news about the stock's value or quality. Consequently, no matter how inopportune this may be from the outset, investors will tend to discount the stock until it is in the firm's interest to reveal the information.", "To test our hypothesis that exercising discretion in disclosing information affects a firm's market price, we partition our sample into two groups: those calls that contain incomplete disclosure and those that do not. Evidence from intra-day stock returns suggests that with regard to a stock's value investors interpret calls marked for incomplete disclosure unfavorably. A participant in the AIMR [2000] corporate disclosure survey supports this finding, stating \"Publicly traded companies have been feeling pressure to be increasingly proactive with a more informed shareholder base. Blind acceptance is no longer acceptable, and the market will punish companies that assume it is.\" Finally, our finding remains robust across alternative return windows.", "Our study contributes to the literature in two ways. First, the transparency of a call enables us to observe the disclosure choices corporate executives make in direct response to requests for information. Prior voluntary disclosure studies (e.g., Nagar, Nanda, and Wysocki [2003], Berger and Hahn [2007]) employ metrics in which the observed disclosure is the outcome of a behind-closed-doors decision process, that is, in a \"managers only\" environment where managers face a presentiment of, rather than a direct demand for, a certain kind of information. In a related paper, Verrecchia and Weber [2006] examine the decision of small firms (i.e., those firms with a market value of equity between $50 and $100 million) to redact material contract or agreement information from their SEC filings. Our paper complements their study by investigating under what conditions managers of large S&P 1500 firms decide to reduce their voluntary disclosure of private information beyond the (presumably proprietary) contract information shared in public meetings. Furthermore, our study contributes to the developing literature that investigates the content of corporate disclosures, such as news releases (e.g., Davis, Piger, and Sedor [2008], Tetlock, Saar-Tsechansky, and Macskassy [2008], Rogers, Van Buskirk, and Zechman [2009]) and conference calls (e.g., Mayew and Venkatachalam [2008], Li et al. [2009]). Tasker [1998b] conducted one of the earliest studies of the content of conference calls, recording and transcribing the content of 12 conference calls held by small-and medium-sized technology firms and analyzing the types of questions analysts on the call asked.", "Second, previous studies have emphasized the advantages, rather than the disadvantages, of the conference call as a disclosure medium. Conference calls are credited with saving time, mitigating selective disclosure problems, providing the opportunity to listen in on others' questions, providing access to more timely information, and not requiring extensive data collection (e.g., Botosan [1997], Frankel, Johnson, andSkinner [1999]). More recent studies, however, recognize that from a company's perspective hosting a conference call also entails a potential disadvantage compared with more traditional (i.e., one-way) disclosure channels. The unscripted format of the question-and-answer section of the call enables participants to prompt management to reveal private information by asking any type of questions, including those requesting information that managers do not (yet) want to reveal. To avoid this undesirable event, corporate executives often discretionarily field questions from analysts of their choosing. Indeed, prior research supports the idea that managers grant sell-side analysts, who generally have more favorable views of the firm, more access to private managerial information (e.g., Chen and Matsumoto [2006], Mayew [2008]). Nevertheless, despite this seemingly effective discretionary tool, participants persist in requesting private information during a conference call that management is reluctant or unable to provide at the time.", "The remainder of this paper proceeds as follows. Section 2 discusses the disclosure role of earnings-related conference calls and provides a short review of the literature. Section 3 presents the procedure for selecting our sample and developing our proxies. Section 4 presents development of our hypotheses and measurement of our variables. Section 5 reports our findings on the conditions under which corporate executives withhold information from public view. Section 6 reports the results of our investigation into how incomplete disclosure impacts investor trading during the call period. Finally, section 7 concludes."]}, {"paper": "lm2011", "venue": "JF", "head": "", "paragraphs": ["A GROWING BODY of finance and accounting research uses textual analysis to examine the tone and sentiment of corporate 10-K reports, newspaper articles, press releases, and investor message boards. Examples are Antweiler and Frank (2004), Tetlock (2007), Engelberg (2008), Li (2008), and Tetlock, Saar-Tsechansky, and Macskassy (2008). The results to date indicate that negative word classifications can be effective in measuring tone, as reflected by significant correlations with other financial variables.", "A commonly used source for word classifications is the Harvard Psychosociological Dictionary, specifically, the Harvard-IV-4 TagNeg (H4N) file. One positive feature of this list for research is that its composition is beyond the control of the researcher. That is, the researcher cannot pick and choose which words have negative implications. Yet English words have many meanings, and a word categorization scheme derived for one discipline might not translate effectively into a discipline with its own dialect.", "In a survey of textual analysis, Berelson (1952) notes that: \"Content analysis stands or falls by its categories. Particular studies have been productive to the extent that the categories were clearly formulated and well adapted to the problem\" (p. 92). In some contexts, the H4N list of negative words may effectively capture the tone of a text. The question we address in this paper is whether a word list developed for psychology and sociology translates well into the realm of business.", "While measuring document tone using any word classification scheme is inherently imprecise, we provide evidence based on 50,115 firm-year 10-Ks between 1994 and 2008 that the H4N list substantially misclassifies words when gauging tone in financial applications. Misclassified words that are not likely correlated with the variables under consideration-for example, taxes or liabilities-simply add noise to the measurement of tone and thus attenuate the estimated regression coefficients. However, we also find evidence that some high frequency misclassifications in the Harvard list, such as mine or cancer, could introduce type I errors into the analysis to the extent that they proxy for industry segments or firm attributes.", "We make several contributions to the literature on textual analysis. Most notably, we find that almost three-fourths (73.8%) of the negative word counts according to the Harvard list are attributable to words that are typically not negative in a financial context. Words such as tax, cost, capital, board, liability, foreign, and vice are on the Harvard list. These words also appear with great frequency in the vast majority of 10-Ks, yet often do no more than name a board of directors or a company's vice-presidents. Other words on the Harvard list, such as mine, cancer, crude (oil), tire, or capital, are more likely to identify a specific industry segment than reveal a negative financial event.", "We create a list of 2,337 words that typically have negative implications in a financial sense. The prevalence of polysemes in English-words that have multiple meanings-makes an absolute mapping of specific words into financial sentiment impossible. We can, however, develop lists based on actual usage frequency that are most likely associated with a target construct. We use the term Fin-Neg to describe our list of negative financial words. Some of these words also appear on the H4N list, but others, such as felony, litigation, restated, misstatement, and unanticipated do not.", "When testing the 10-K sample, whether tone should be gauged by the entire document or just the Management Discussion and Analysis (MD&A) section is an empirical question. We show that the MD&A section does not produce tone measures that have a more discernable impact on 10-K file date excess returns. Thus, the MD&A section does not allow us to assess tone through a clearer lens.", "In our results, we find that dividing firms into quintiles according to the proportion of H4N words (with inflections) in their 10-Ks produces no discernable pattern. That is, the proportion of H4N words does not systematically increase as 10-K filing returns decrease. However, when we use our financial negative list to sort firms, we observe a strong pattern. Regressions with multiple control variables confirm the univariate findings of no effect for the proportional counts from the Harvard list versus a significant impact for the Fin-Neg list.", "We also show that the attenuation bias introduced by misclassifications, especially by high frequency words (which may be overweighted based on simple proportional measures), can be substantially mitigated by using term weighting. Most textual analysis uses a \"bag of words\" method where a document is summarized in a vector of word counts, and then combined across documents into a term-document matrix. In other disciplines, term weighting is typically used in any vector space representation of documents. 1 With term weighting, where the enormous differences in frequencies are dampened through a log transformation and common words are weighted less, both the Harvard list and our Fin-Neg list generally produce similar results.", "To expand the word classification categories, we create five additional word lists. Specifically, in addition to the negative word lists, we consider positive, uncertainty, litigious, strong modal, and weak modal word categories. 2 When we assess whether these word lists actually gauge tone, we find significant relations between our word lists and file date returns, trading volume, subsequent return volatility, standardized unexpected earnings, and two separate samples of fraud and material weakness. We also examine whether negative tone classifications are related to future returns in terms of a trading strategy, and find no evidence of return predictability based on the competing measures.", "The nature of word usage in firm-related news is not identical across media. Whether our results hold for samples beyond 10-Ks is an important question. We provide preliminary evidence in alternative contexts showing that in comparison with the Harvard list, the Fin-Neg list has larger correlations with returns in samples of seasoned equity offerings and news articles.", "The remainder of the paper is organized as follows. Section I discusses related research on textual analysis. Section II introduces the data sources, variables, and term weighting method used in our analysis. Section III describes the various word lists and Section IV reports the empirical results. Finally, Section V concludes."]}, {"paper": "ragozzino2024", "venue": "journal(LRP)", "head": "Introduction", "paragraphs": ["Asymmetric information plays a central theoretical role in corporate strategy (e.g., Balakrishnan and Koza, 1993;Vanhaverbeke et al., 2002;Villalonga and McGahan, 2005;Higgins and Rodriguez, 2006;Schildt and Laamanen, 2006;Capron and Shen, 2007;Graebner, 2009;Zaheer et al., 2010;Cuypers et al., 2017;Humphrey-Jenner et al., 2017). Many corporate transactions are characterized by some level of information asymmetry, and this leads a less informed buyer to face adverse selection, or the risk of overpaying for assets (e.g., Akerlof, 1970;Ravenscraft and Scherer, 1987;Healy and Palepu, 1993;Healy and Palepu, 2001). It is also relatively well understood that the hazards associated with information asymmetry tend to be greater when the value of a transaction is significant to a buyer, and when the transaction is a one-off deal, rather than an ongoing relationship that will have buyers and sellers engage in repeat business over time (Riley, 2001). As a consequence, mergers and acquisitions (M&A) are especially prone to adverse selection concerns.", "M&A also happen to be a pervasive investment vehicle supporting corporate strategy: According to the specialized analytics and technology company Dealogic, the yearly dollar volume of worldwide activity has ranged between $2.2 and $4.1 trillion during the 2015-2019 timeframe. 1 Given the economic importance of M&A and firms' exposure to adverse selection in these deals, academic studies in strategy, finance, and other fields have devoted significant attention to examining the implications of adverse selection for M&A deals and firm performance. The evidence brought forth by this body of work confirms the broad point that adverse selection plays a role in explaining firms' M&A strategy and performance (e.g., Fowler and Schmidt, 1989;Villalonga and McGahan, 2005;Moeller et al., 2007;Chemmanur et al., 2009;Officer et al., 2009;Cheng et al., 2016;Cuypers et al., 2017;Martin and Shalev, 2017;Yakis-Douglas et al., 2017;Borochin et al., 2019).", "Despite this fairly clear-cut conclusion, it is noteworthy that prior work has focused mostly on the asymmetric information present between the buying and the selling firms in M&A and the implications it presents during M&A dealmaking. This work has applied the theoretical models of information economics originally developed for other markets to the M&A market context, in order to understand the antecedents and consequences of various aspects of M&A transactions. Specifically, M&A studies have relied on seminal research such as Akerlof's (1970) classic model of used car markets, Spence's (1973) model of signaling in labor markets, and Stiglitz's (1973) analysis of insurance markets (e.g., Reuer, 2009). The upshot of research on M&A is that under conditions of information asymmetry, deals may fall through, or alternative entry modes may be used, absent other remedies such as contractual provisions or payment structures to reduce the exposure of buyers to adverse selection risks (e.g., Balakrishnan and Koza, 1993;Kohers and Ang, 2000;Datar et al., 2001;Gilson and Schwartz, 2005;Cain et al., 2011;Reuer and Ragozzino, 2012;Macias and Moeller 2016;McCann et al., 2016).", "However, there is a separate adverse selection problem in M&A markets that has often been neglected in previous research (for an exception see Yakis-Douglas et al., 2017): Information asymmetry may also exist between company executives carrying out M&A and the very shareholders they represent. This means that even if a buyer were to address information asymmetry satisfactorily between itself and a seller during deal negotiations, it would still face the critical challenge of relaying its M&A strategy to shareholders. It is noteworthy that such third parties often do not appear in other market settings involving buyers and sellers in which the original models of adverse selection were based (e.g., the original models applied to used cars, labor markets, insurance, etc.). For shareholders, the more complex the transaction is, the higher their information-gathering costs will be, and they obtain diminishing benefits from trying to make sense of the firm's deals (Veldkamp, 2006). As the information becomes costly to gather or process, shareholders can discount the value of the firm and firms will experience a higher cost of obtaining external resources. 2 It follows that the consequences of information asymmetries in M&A markets might even be more far-reaching than previous M&A studies on this topic have considered, and the costs they entail for acquirers have been understated. This oversight may be in part due to the greater attention that corporate strategy scholars have given to moral hazard concernsanother implication of information asymmetry involving shareholders that can give rise to value destroying acquisitions (e.g., Jensen and Meckling, 1976;Dalton et al., ). Alternatively, scholars may have overlooked adverse selection in this context because they have implicitly assumed that capital markets are informationally efficient (Fama, 1970;Milgrom and Stokey, 1982). 3 Regardless, for the most part research in the area of corporate strategy in general, as well as M&A in particular, has neglected the importance of adverse selection between company insiders and shareholders. A recent notable exception is the work by Benner and Zenger (2016), who have provided a conceptual discussion of the challenges managers face when they devise and implement complex strategies and subsequently have to relay information on these strategies to capital market participants.", "We wish to build on these ideas and join them with information economics research on M&A. We do so by examining whether M&A carries important implications for information asymmetries in capital markets and their operation. We first set out to investigate whether the information disclosures by company insiders to shareholders follow a pattern that is consistent with the company's strategic complexity, as defined by its M&A activity in particular. To this end, we track companies' information disclosures by using a comprehensive set of earnings calls transcripts spanning 12 years and over 6,000 unique companies and millions of exchanges between executives and analysts. In particular, we are able to isolate the corporate strategy terms spoken by company executives and analysts during earnings calls. Further, in view of potential endogeneity concerns, we adopt a propensity score matching technique to create comparable samples of M&A-active and M&A-inactive firms, as well as of firms engaged in different levels of M&A activity.", "Our results demonstrate that the M&A strategies implemented by companies affect their information exchanges with analysts, both in terms of questioning by analysts and the information disclosures by executives. For future research, these findings provide initial evidence that executives engaging in M&A are not only contending with information asymmetries directly in M&A markets with targets during deal-making, but also in other factor markets as well (i.e., capital markets). We therefore conclude that previous M&A research has understated the consequences of the inefficiencies and frictions presented by information asymmetries surrounding acquisition deals. In subsequent analyses, we also show that the magnitude of analysts' earnings forecast errors increases with their doubts regarding a firm's strategy and decreases with the information conveyed by executives during earnings calls. In summary, we offer fine-grained evidence that information disclosure is proportional to the complexity of the firm's M&A strategy, and that richer disclosure by executives and more intense questioning by analysts have a direct impact on the ability of information intermediaries in capital markets to evaluate firms.", "As its main contribution, this study provides both conceptual arguments and empirical evidence that the strategic complexity of firms' M&A strategies needs to be articulated to shareholders, in order for the latter to acquire the necessary information to evaluate 2 Paradoxically, as noted in recent work, the more unique a firm's corporate strategy, the more difficult it is to communicate it effectively to shareholders, yet it is through a unique and complex corporate strategy that economic rents are possible in the first place due to inimitability (i.e., Litov et al., 2012). 3 The definition of strong form market efficiency is that of a market in which prices reflect all public and private information. Effectively, this definition rules out the problem of adverse selection between company insiders and shareholders, because any deviation in price from the true value of the firm must be random, and not due to a recurring problem of information asymmetry between some firm stakeholders and others. Whether and when assumptions about different levels of market efficiency are warranted is beyond the scope of this paper, and we direct readers interested in this topic to the pertinent work in financial economics (e.g., Grossman and Stiglitz, 1980;Shiller, 1989).", "complex transactions by these firms. For the M&A literature, the evidence underscores the point that executives are not only called upon to implement M&A strategies that have the potential of conferring a competitive advantage to their firmsan arduous task in itself given the frequency with which acquirers fail to capture value due to information costs and other challengesbut they are also called upon to articulate the corporate strategy surrounding their investment decisions to the investing public. Our arguments and findings therefore call for future research that bridges economic transactions in certain factor markets (e.g., M&A) with information disclosures in others (e.g., capital markets) to account more fully for the consequences of information frictions affecting corporate strategy."]}, {"paper": "thewissen2024", "venue": "working(SSRN)", "head": "", "paragraphs": ["1. Stock-for-stock mergers and acquisitions (M&As) strategically inflate the tone of earnings press releases during the year preceding the M&A announcement, aiming to diminish the target acquisition cost. 2. The analysis reveals a significant surge of 15.32% in the tone of earnings press releases during the premerger period, resulting in substantial estimated savings of $21.777 million for the average stock bidder in acquisition costs. 3. The degree of tone manipulation exhibits variations based on specific factors: larger deals, firms with lower historical performance, and firms lacking robust monitoring mechanisms experience a stronger inclination towards tone inflation. 4. A consequential outcome of this deliberate tone manipulation is the emergence of negative long-term returns subsequent to the M&A announcement. 5. We also find that, prior to the announcement of a merger or acquisition (M&A), bidders tend to manipulate the corporate narrative structure by deliberately amplifying positive tone dispersion within their earnings press releases, thereby enhancing the overall impact of their tone inflation strategy."]}, {"paper": "thewissen2024", "venue": "working(SSRN)", "head": "Introduction", "paragraphs": ["Although mergers and acquisitions (M&As) activity has significantly grown over the last decade, there remains much about the M&A process that we need to comprehend, including the implication of the method of payment on managers' opportunistic behavior. 1 The use of stock as a method of payment is also known to create a strong incentive for managers to manipulate earnings to positively influence the stock price, and therefore reduce the target's acquisition cost (Erickson and Wang, 1999;Louis, 2004).", "However, it remains unclear whether stock bidders also strategically vary the narrative content of their corporate disclosures. Given the substantial influence of qualitative information on the firm's stock price (Henry, 2008;Henry and Leone, 2016;Fu, Wu, and Zhang, 2021;Arslan-Ayaydin, Boudt, and Thewissen, 2016), it is essential to examine whether the use of stock as a form of payment leads managers to manipulate the content of qualitative information in corporate disclosures.", "In the majority of M&As, the acquiring firm buys the target's assets using cash. However, in some cases, the acquiring firm uses its stock in exchange for the target's stock. In stock-for-stock mergers, acquiring firms exchange their stock against the stock of the target at a predefined rate.", "This means that the higher the price of the acquiring firm's stock on the agreement date, the fewer the number of shares that must be issued to purchase the target firm. Prior literature shows that such a negative relationship between bidders' stock price and shares issued in the transaction leads bidders to increase their own premerger stock price to lower the target's acquisition cost. For instance, Erickson and Wang (1999), Louis (2004) and Higgins (2013) find that acquiring firms tend to manipulate total accruals upwards in the periods prior to the merger announcement, while He, Liu, Netter, and Shu (2020) find that bidders significantly manage down analyst earnings forecasts prior to merger announcements. Overall, prior research provides strong evidence that the information environment around stock-for-stock mergers is characterized for being highly uncertain and subject to opportunistic manipulation. 1 The method of payment in a M&A transaction can either be cash, stock (in which an exchange ratio is specified for conversion of target shares into acquirer shares), or a combination of the two (mixed deals).", "This preprint research paper has not been peer reviewed. Electronic copy available at: https://ssrn.com/abstract=4900453 P r e p r i n t n o t p e e r r e v i e w e d 3 Yet, there remains limited research on whether bidders in stock-for-stock mergers tend to manipulate the content of corporate disclosures to increase their stock price. Disclosure tone measures both what and how information is disclosed (Loughran and McDonald, 2011), reflecting both firms' performance and managers' disclosure incentives (Fu et al., 2021). A growing body of literature highlights that the narrative section of corporate disclosures provides incremental information to financial numbers and management forecasts in explaining the firm's future cash flows (Henry, 2008;Henry and Leone, 2016;Baginski, Demers, Kausar, and Yu, 2018;Arslan-Ayaydin et al., 2016;Cho, Phillips, Hageman, and Patten, 2009;Cho, Roberts, and Patten, 2010;Davis, Piger, and Sedor, 2012). However, managers can also use the tone as a tool to mislead stakeholders. Arslan-Ayaydin et al. (2016) show that CEOs' equitybased incentives leads managers to inflate the tone of earnings press releases, while Henry, Thewissen, and Torsin (2021) find that a cautious disclosure tone mitigates potential home bias-related credibility and asymmetric information concerns arising from cultural and institutional distance. In this paper, we therefore extent prior research and propose that, in order to increase their stock price and reduce the acquisition cost of the target, bidders in stock-for-stock mergers inflate the tone of corporate disclosures.", "It is not ex ante obvious whether the potential gains outweigh the costs of inflating the tone of their corporate disclosures. First, it is unclear whether acquirers would be willing to exaggerate the use of positive news at the cost of reducing their credibility with regard to investors. That is, if the manager's optimism is inappropriate, investors may be potentially misled in terms of the current and future earnings and firm value of the newly combined corporation. The company's credibility may be jeopardized (Yuthas, Rogers, and Dillard, 2002), along with the reliability, value, and trust in their corporate communication. In addition, litigation risks are a significant cost associated with tone inflation in qualitative disclosures. According to Rogers, Van Buskirk, and Zechman (2011a), the use of optimistic language by managers heightens litigation risk. Their research indicates that plaintiffs often target optimistic statements in their lawsuits and that companies facing lawsuits tend to have unusually optimistic language in their earnings announcements. Therefore, the fear of litigation due to overly optimistic voluntary disclosures can discourage managers from being overly optimistic in their", "This preprint research paper has not been peer reviewed. Electronic copy available at: https://ssrn.com/abstract=4900453 P r e p r i n t n o t p e e r r e v i e w e d communications, especially during high-profile events like stock-for-stock mergers. In fact, Ball and Shivakumar (2008) question the notion that managers manipulate earnings upwards before stock issuance because of the high market scrutiny and litigation risk that characterize these events. Finally, the target and its advisors are informed professionals and users of accounting information. As such, they are likely to be familiar with the tone inflation used by the bidder. In light of this manipulation of corporate narratives, the target may oppose and reject the deal.", "Against this backdrop, whether stock-for-stock acquirers engage in tone manipulation is not only an empirical question, but also raises ethical concerns as effective information disclosure and information transparency are key aspects of corporate ethical behavior that could build stakeholder trust and sustainable competitive advantage (das Neves and Vaccaro, 2013). Despite being exposed to several costs associated with the manipulation of narrative disclosures, the question is therefore whether stockfor-stock bidders engage in the upward manipulation of the tone of their voluntary corporate disclosure.", "This question is of interest, given that both quantitative and qualitative features are used to evaluate managerial abilities and firm performance (Amir and Lev, 1996;Arslan-Ayaydin, Bishara, Thewissen, and Torsin, 2020). We start by examining the use of tone management before M&A announcements, and specifically, whether bidders in stock mergers are more likely to inflate the tone of earnings press releases. We then conduct additional cross-sectional tests to analyze the impact of the acquiror's premerger performance, deal value and firm monitoring on bidders' propensity to manipulate qualitative information. We further study how this manipulation of qualitative content, if used, impacts bidders' stock prices and, in turn, their acquisition costs.", "We use a sample of 5,558 M&A deals between 2004 and 2020, including 302 stock deals, 4,088 hybrid deals (takeovers that use both cash and stock) and 1,168 cash deals. To measure the linguistic tone, we follow prior literature (see, e.g., Henry and Leone, 2016) and compute the spread in the number of positive and negative terms in the earnings press release from the Henry (2008) lists of words. We follow prior M&A literature and examine quarterly earnings press releases of bidder firms over five quarters before the merger announcement. We find that the tone of earnings press releases for stock-for-stock mergers significantly increases in the four quarters before the M&A announcement quarter to reach a", "This preprint research paper has not been peer reviewed. Electronic copy available at: https://ssrn.com/abstract=4900453 P r e p r i n t n o t p e e r r e v i e w e d peak two quarters ahead of the M&A announcement. In fact, the median (average) tone increases by 15.320% (4.447%) between quarter -6 and quarter -2. In the quarter of the M&A announcement and the subsequent quarters, we observe that the tone of earnings press releases returns to its original level and no longer significantly differs from that of cash-based deals.", "In contrast, we find that the tone of earnings press releases of cash deals does not significantly change over the five quarters before the M&A announcement, which is in line with the lack of incentive to engage in tone management in these deals. Controlling for a series of deal and firm characteristics, as well as year and industry fixed effects, the multivariate analysis confirms that the tone of stock deals significantly increases before the M&A announcement, relative to cash deals. Our analyses further indicate that the degree of tone inflation increases with the deal size, but decreases with the presence of control mechanisms in the firm and the firm's past performance.", "Overall, our results are consistent with the strategic manipulation of tone by bidding firms in the period prior to the announcement of the merger agreement. To further ensure that our results are not driven by confounding factors, we conduct a number of identification tests for alternative explanations.", "We first examine the impact of earnings manipulation and explore whether the upward effect of stock deals on tone is a separate effect and cannot be explained by upward earnings management (Erickson and Wang, 1999). If the more optimistic tone of firms is mostly driven by the manipulation of earnings numbers, the impact of stock deals on the content of earnings press releases should become statistically insignificant once we control for earnings management. Contrary to this perspective, our findings reveal that the relationship between stock deals and tone continues even with upward earnings management. This indicates that stock deals cause managers to consistently manipulate the content of earnings press releases, independent of their earnings management practices.", "A second potential concern is that unobserved characteristics correlated with the method of payment explains the tone of earnings press releases. We therefore correct for this potential endogeneity between tone and the method of payment by conducting five tests to exclude the possibility that alternative variables explain the impact of the method of payment on the tone. We first follow Fisch and Momtaz (2020) and employ a restricted control function regression. We then exploit an instrumental variable", "This preprint research paper has not been peer reviewed. Electronic copy available at: https://ssrn.com/abstract=4900453 P r e p r i n t n o t p e e r r e v i e w e d approach using investors' ownership as instrument. We then also compare stock and cash bidders using the propensity score matching (PSM) and entropy-balancing methods. Finally, we conduct two pseudo-events studies by shifting merger announcements either forward or backward by four quarters and repeat our baseline regressions. Although no approach can perfectly rule out endogeneous relationships, our results from our endogeneity tests provide supporting evidence that bidders' tone inflation is likely to be caused by the use of stock payment and not by omitted bidder-, target-, deal-specific characteristics.", "Based on this causal evidence, we next estimate the impact of inflating the tone of earnings press releases on stock bidders before the merger. To do this, we conduct several regressions of a bidder's abnormal stock return around earnings announcements on the abnormal tone in earnings press releases.", "Controlling for other firm-, year-and industry-specific characteristics, we find that increasing the tone of earnings press releases is significantly associated with an increase in pre-merger stock prices. In fact, we estimate that tone inflation leads to savings in acquisition costs of $21.777 million for an average stock bidder in the pre-merger period. In addition, we examine the impact of this tone inflation on bidders' abnormal stock returns around and after the merger announcement. If the tone inflation is opportunistic, we expect the abnormal tone in earnings press releases to cause a temporary overpricing of bidders' stocks at the M&A announcement and its effect to reverse in the long run. In line with this prediction, our results show that stock-for-stock bidders who engage in tone inflation benefit from superior returns at the M&A announcement. However, in the long-term, we document that stock bidders suffer from worse long-term returns. This evidence is in line with prior research on earnings management, which documents that firms that manipulate earnings to beat expectations are still able to benefit from higher short term returns, but suffer from long term losses (Bartov, Givoly, and Hayn, 2002;Sloan, 1996).", "Our study adds to the literature in several ways. First, motivated by prior research on the relation between disclosure tone and stock valuation, our study provides novel empirical evidence on the impact of M&As' method of payment on managers' strategic motives. In particular, we contribute to Erickson and Wang (1999), Higgins (2013), He et al. (2020) and Louis (2004) by showing that influencing investors' decisions is not only achieved by manipulating hard financial information, but also the content", "This preprint research paper has not been peer reviewed. Electronic copy available at: https://ssrn.com/abstract=4900453 P r e p r i n t n o t p e e r r e v i e w e d of disclosure narratives. As such, the management of tone should be regarded as an independent and distinct manipulation tool utilized by acquirers in an attempt to inflate the stock price around stock-forstock M&As.", "Second, this paper adds to prior literature on voluntary disclosure by examining how important economic events influence the quality of corporate narratives (see, e.g., Erickson and Wang, 1999;Louis, 2004;He et al., 2020;Henry et al., 2021). Instead of focusing on the identification of new methods to optimize the definition of tone in corporate disclosures (Jegadeesh and Wu, 2013;Loughran and McDonald, 2011;Boudt and Thewissen, 2019), our study aims at highlighting the strategic motives that may lead managers to manipulate the content of such information and how the stock market responds to such manipulation. Our focus on one of the most important events in a company's lifetime (e.g., M&As)", "clearly illustrates that the content of corporate narratives has both information-sharing purposes and strategic motives to influence the stock price (Yan, Aerts, and Thewissen, 2019). As such, our results help investors understand the informational dynamics around stock-for-stock M&As and better comprehend the influence of managerial incentives on corporate reporting and the firm's value in the short and long term around M&A events.", "Third, our paper highlights an important ethical concern with respect to the quality of the narratives contained in corporate disclosures. Our findings indicate that acquirers put forward events that serve at inflating the stock price, rather than being accountable to the firm's stakeholders and to the society. As such, the opportunistic use of corporate disclosures as an instrument to construct reality in a way that benefits bidders at the expense of the target represents an ethical issue, as \"it sustains relations of domination\" (Beelitz and Merkl-Davies, 2012, p. 102). Many questions have been raised concerning the ethical propriety of these relations of domination in the context of M&As. Most of these relate to the tactics used by the target when trying to avoid being acquired (for a discussion, see; Werhane, 1988), such as the poison-pill tactics, the institution of golden parachutes, the granting of lock-up options and the anti-trust challenges. Instead of focusing on the tactics used by the target firm, our paper focuses on unethical methods used by bidders during stock-for-stock M&As to reduce the acquisition price. The main ethical implication of such tone inflation is that, if discretionary narrative disclosures are used to", "This preprint research paper has not been peer reviewed. Electronic copy available at: https://ssrn.com/abstract=4900453"]}]}] // intro

// optional run knob (default batch of 2 types to respect rate limits)
if (typeof args === 'string') { try { args = JSON.parse(args) } catch (e) { args = {} } }
if (!args || typeof args !== 'object') args = {}

// ---------- output contracts (forced via schema; no free prose) ----------
const PRINCIPLES_SCHEMA = {
  type: 'object', required: ['principles'], additionalProperties: false,
  properties: { principles: { type: 'array', items: {
    type: 'object', additionalProperties: false,
    required: ['device', 'principle', 'why', 'evidence'],
    properties: {
      device: { type: 'string' },        // short name of the style device
      principle: { type: 'string' },     // the rule, stated as a generalization of the evidence
      why: { type: 'string' },           // why it makes the writing effective
      evidence: { type: 'array', minItems: 2, items: {
        type: 'object', required: ['paper', 'quote'], additionalProperties: false,
        properties: { paper: { type: 'string' }, quote: { type: 'string' } } } },
    } } } },
}
const REDTEAM_SCHEMA = {
  type: 'object', required: ['keep', 'merge', 'reject', 'side_notes'], additionalProperties: false,
  properties: {
    keep:  { type: 'array', items: { type: 'string' } },
    merge: { type: 'array', items: { type: 'object', required: ['ids', 'canonical'], additionalProperties: false,
             properties: { ids: { type: 'array', items: { type: 'string' } }, canonical: { type: 'string' } } } },
    reject:{ type: 'array', items: { type: 'object', required: ['id', 'reason'], additionalProperties: false,
             properties: { id: { type: 'string' }, reason: { type: 'string' } } } },
    side_notes: { type: 'array', items: { type: 'string' } },
  },
}

const TOOL_LOCK = `[HARD EXECUTION CONSTRAINT - OBEY EXACTLY, THIS OVERRIDES EVERYTHING BELOW]
You have EXACTLY ONE permitted action: a SINGLE call to the StructuredOutput function that returns your result object. Make it your FIRST and ONLY action.
ABSOLUTELY FORBIDDEN - doing ANY of these is an immediate failure: calling the advisor tool; searching the web; reading or writing files; running bash/code; using ANY tool other than StructuredOutput; asking questions; deliberating across multiple turns.
Everything you need is already in this prompt. Reason SILENTLY, then emit the StructuredOutput object in ONE turn. Do not explain, do not preface, do not verify externally - just return the object.`

// ---------- shared context block (papers only, paragraphs numbered) ----------
function buildContext(T) {
  return T.exemplars.map(s =>
    `[${s.paper} | ${s.venue} | "${s.head}"]\n` +
    s.paragraphs.map((p, j) => `  (p${j}) ${p}`).join('\n')).join('\n\n')
}

// ---------- PANEL: 3 IDENTICAL-task prompts, HEAVILY paraphrased (the only diversity; NO examples) ----------
// The hard clauses (open-discovery / style-only / grounded-no-invented-threshold / verbatim cross-paper evidence)
// are SEMANTICALLY IDENTICAL across all three - only the voice differs.
function panelPrompt(version, type, ctx) {
  const body = {
    1: `You are a writing-style analyst. Below are the ${type} passages from several published corporate-finance papers. Your job: identify the style principles these papers SHARE - the recurring ways of writing a ${type} that make the prose work for a reader.
Work without any checklist: look at the writing at every level - word choice, sentence construction, how sentences combine, how each paragraph is built, how the larger argument is staged - and capture the MAJOR, load-bearing principles - the handful that most define how these papers write a ${type}. Consolidate related observations under one principle; do not split every micro-variation into its own rule. Aim for a short, high-level list, not an exhaustive catalogue.
Capture STYLE, never substance: a principle is about HOW these papers write, not WHAT they find or claim. Set aside their results, data, and domain content entirely.
Stay grounded: every principle must be one the passages genuinely exhibit, stated as a generalization of what you see. Never assert a numeric threshold - a word count, a sentence length, a ratio - that the passages do not themselves establish.
Evidence is mandatory and must be exact: each principle carries at least two quotes copied character-for-character from the passages above, drawn from at least two DIFFERENT papers, with the source paper named on each quote. A quote that is not an exact copy is discarded automatically, so transcribe precisely.
Give, per distinct principle: a short device name, the principle stated plainly, why it makes the writing effective, and its evidence.`,
    2: `Read the ${type} passages below - each is the ${type} of a corporate-finance paper. Work out what these writers DO IN COMMON when they craft a ${type}: the shared craft, the repeated moves, the habits of construction that give this kind of section its characteristic, readable form.
Do not work from a fixed list. Examine the prose top to bottom - diction, the shape of individual sentences, the way sentences are joined, paragraph architecture, the sequencing of the whole - and name the FEW principles that genuinely characterize this register. Fold closely-related devices together under one principle rather than itemizing every surface variation; a tight set of high-level principles beats a long catalogue of fine-grained ones.
Keep strictly to STYLE. You are describing the MANNER of writing, not the content - findings, numbers, and subject matter are out of scope.
Anchor every claim in the text: state each principle as a pattern the passages actually display; do not invent a fixed measurement - length caps, counts, proportions - the passages never set.
Prove each one: every principle needs two or more quotations lifted verbatim, exactly as written, from two or more SEPARATE papers, each tagged with the paper it came from. Inexact quotes are dropped by an automatic check, so copy them letter-perfect.
For each principle provide: a brief device name, the principle itself, the reason it works on the reader, and the quotes.`,
    3: `Below are ${type} sections from a set of corporate-finance papers. Reverse-engineer the writing: which shared principles of style do these ${type}s follow? You are after the patterns common ACROSS the papers - the recurring authorial choices behind this section type's readable form.
No checklist - discover, do not confirm. Inspect every layer of the writing, from word and sentence up through paragraph and overall arrangement, and distill the SMALL set of principles that most define this section's craft. Group kindred devices into one principle instead of cataloguing every minor variant; prefer a concise list of major principles over exhaustive coverage.
Confine yourself to STYLE - the how, not the what. The papers' claims, evidence, and topic are out of scope; only the writing craft is in scope.
Stay tethered to what is on the page: each principle must be visibly present in the passages and phrased as a generalization of that evidence - never a concocted threshold (no invented word limits, sentence counts, or ratios the text does not itself fix).
Back each principle with proof: at minimum two quotes, reproduced exactly as printed, taken from at least two DISTINCT papers, each labeled with its paper. A quote that is not an exact substring is discarded automatically, so copy with care.
Report, per principle: a short device label, the stated principle, why it is effective, and the supporting quotes.`,
  }[version]
  return `${TOOL_LOCK}\n\n${body}\n\n===== ${type.toUpperCase()} PASSAGES (corporate-finance papers) =====\n${ctx}\n\n===== RETURN =====\nReturn your principles via the structured tool. Your returned object IS the data, not a message.`
}

// ---------- RED TEAM: scrutinize + merge BY REFERENCE (its own role; gets the FULL evidence) ----------
function redteamPrompt(type, clean) {
  return `${TOOL_LOCK}

You are the RED TEAM for the "${type}" writing-style principles. Three panel agents independently produced the principles below; each carries an ID. Every quote has ALREADY been verified verbatim by a script and located to its paper and paragraph - do NOT re-check quotes.

Your job is SCRUTINIZE + SYNTHESIZE, BY REFERENCE ONLY. You never write or reword a principle; you emit decisions that reference IDs.

SCRUTINIZE - reject a principle when ANY of these holds:
- its quotes do not actually exhibit the device it names (the evidence does not show the claimed pattern);
- it asserts an absolute threshold - a fixed word count, sentence length, or ratio - that its evidence does not establish;
- it describes content, findings, or subject matter rather than writing style;
- it is too vague to act on.
Put each rejected ID in reject{id,reason}.

SYNTHESIZE - across the three agents, principles that name the SAME underlying device are duplicates: group their IDs and name ONE canonical to keep (tiebreak: the one with more / more authoritative evidence - published JF, JAR, QJE outweigh working papers). Where two principles are genuinely DISTINCT devices, keep them separate rather than folding them together.
- keep: IDs that survive as-is.
- merge: [{ids, canonical}].
- side_notes: ONLY coverage-gap flags for a human (e.g. a level of the writing all three agents left unexamined). NEVER new principles.

You invent nothing. The main loop copies the kept/canonical principles verbatim.

===== PRINCIPLES =====
${JSON.stringify(clean.map(f => ({ id: f.id, agent: f.agent, device: f.device, principle: f.principle, why: f.why, evidence: f.evidence })), null, 1)}

Return decisions via the structured tool.`
}

// ---------- deterministic in-script gate (pure JS, no LLM) ----------
// forgiving normalization: fold unicode quotes/dashes to ASCII, drop punctuation + stray
// digit-runs (inlined footnote markers), collapse whitespace. Both sides normalized identically.
function norm(s) {
  return (s || '')
    .toLowerCase()
    .replace(/[\u2018\u2019\u201b\u2032]/g, "'")   // fold unicode single quotes/prime
    .replace(/[\u201c\u201d\u2033]/g, '"')          // fold unicode double quotes
    .replace(/[\u2010-\u2015\u2212]/g, '-')         // fold unicode dashes/minus
    .replace(/[^\w]+/g, ' ')      // punctuation -> space
    .replace(/\b\d+\b/g, ' ')     // drop standalone digit runs (footnote numbers, stray refs)
    .replace(/\s+/g, ' ')
    .trim()
}
function isSub(q, hay) { const n = norm(q); return n.length > 0 && norm(hay).includes(n) }

// ================= per-type pipeline (fully independent) =================
async function runType(T) {
  const ctx = buildContext(T)
  const raw = await parallel([1, 2, 3].map(v => () =>
    agent(panelPrompt(v, T.type, ctx), { schema: PRINCIPLES_SCHEMA, phase: `Panel:${T.type}`, label: `${T.type}/panel-${v}` })))

  const byPaper = {}   // accumulate ALL paragraphs per paper (a paper appears as many section-entries; don't overwrite)
  for (const s of T.exemplars) (byPaper[s.paper] = byPaper[s.paper] || []).push(...(s.paragraphs || []))

  const clean = [], rejected = []
  raw.forEach((r, ai) => (r && r.principles || []).forEach((pr, pi) => {
    const id = `a${ai + 1}-p${pi + 1}`
    const ev = pr.evidence || []
    // GATE: each quote must be verbatim in its CLAIMED paper (no all-papers fallback, so "2 papers"
    // cannot be faked by a mislabel); compute the true paragraph index as a reliable locator.
    const located = []
    let allMatch = ev.length > 0
    for (const q of ev) {
      const ps = byPaper[q.paper]
      const idx = ps ? ps.findIndex(p => isSub(q.quote, p)) : -1
      if (idx < 0) { allMatch = false; break }
      located.push({ paper: q.paper, para_idx: idx, quote: q.quote })
    }
    const distinctPapers = new Set(located.map(l => l.paper))
    const cardOK = ev.length >= 2 && distinctPapers.size >= 2
    if (allMatch && cardOK) clean.push({ id, agent: ai + 1, device: pr.device, principle: pr.principle, why: pr.why, evidence: located })
    else rejected.push({ id, reason: !allMatch ? 'quote_not_verbatim_in_claimed_paper' : 'need_2_distinct_papers' })
  }))
  log(`[${T.type}] ${clean.length} passed gate, ${rejected.length} rejected`)
  if (clean.length === 0) return { type: T.type, principles: [], gate_rejected: rejected, redteam_rejected: [], merges: [], unhandled: [], side_notes: [], note: 'no principles survived the gate' }

  const decisions = await agent(redteamPrompt(T.type, clean), { schema: REDTEAM_SCHEMA, phase: `Redteam:${T.type}`, label: `${T.type}/redteam` })
  if (!decisions) {   // redteam died (timeout/error) -> degrade gracefully, never crash the type
    log(`[${T.type}] redteam returned NULL -> degrading to ${clean.length} gate-clean principles (no merge/verify)`)
    return { type: T.type, principles: clean, gate_rejected: rejected, redteam_rejected: [], merges: [], unhandled: [], side_notes: ['REDTEAM FAILED (null) - principles are raw gate-clean, NOT deduped/verified; re-run this type'], note: 'redteam_failed' }
  }
  const byId = {}; clean.forEach(f => { byId[f.id] = f })
  const rejectIds = new Set((decisions.reject || []).map(r => r.id))
  const keepIds = new Set((decisions.keep || []).filter(id => !rejectIds.has(id)))
  ;(decisions.merge || []).forEach(m => { if (m.canonical && !rejectIds.has(m.canonical)) keepIds.add(m.canonical) })
  let principles = [...keepIds].map(id => byId[id]).filter(Boolean)
  if (principles.length === 0 && clean.length > 0) {   // keeps-0 -> degrade (the Phase-2 Bug-3 fix)
    log(`[${T.type}] red-team kept 0 of ${clean.length} (decision IDs unmatched) -> degrading to gate-clean`)
    return { type: T.type, principles: clean, gate_rejected: rejected, redteam_rejected: decisions.reject || [], merges: decisions.merge || [], unhandled: [], side_notes: (decisions.side_notes || []).concat(['RED-TEAM kept 0 - degraded to gate-clean (un-deduped); re-run this type']), note: 'redteam_zero_degraded' }
  }
  const handled = new Set([...keepIds, ...rejectIds])
  ;(decisions.merge || []).forEach(m => (m.ids || []).forEach(id => handled.add(id)))
  const unhandled = clean.map(f => f.id).filter(id => !handled.has(id))
  log(`[${T.type}] ${principles.length} principles kept; ${rejected.length} gate-rejected; ${(decisions.reject || []).length} redteam-rejected`)
  return { type: T.type, principles, gate_rejected: rejected, redteam_rejected: decisions.reject || [], merges: decisions.merge || [], unhandled, side_notes: decisions.side_notes || [], note: 'ok' }
}

// ================= body: independent types, batched to respect rate limits =================
phase('Panel')
log('[input] ' + TYPES.map(T => `${T.type}:${T.exemplars.length}papers/${T.exemplars.reduce((n, s) => n + (s.paragraphs || []).length, 0)}paras`).join('  '))
const MAXT = Math.max(1, args.maxTypes || 2)
const results = []
for (let i = 0; i < TYPES.length; i += MAXT) {
  const batch = await parallel(TYPES.slice(i, i + MAXT).map(T => () => runType(T)))
  results.push(...batch.filter(Boolean))
}
return { types: TYPES.map(t => t.type), results }